import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.q07Y7wJQ.js";var i=JSON.parse(`{"title":"Introduction","description":"","frontmatter":{"prev":{"text":"Home","link":"/"},"next":{"text":"Icon","link":"/documentation/icon"}},"headers":[],"relativePath":"documentation/index.md","filePath":"documentation/index.md","lastUpdated":1788551488000}`),a={name:`documentation/index.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h1><p><strong>Excellent Data Filler</strong> is a modern, privacy-focused browser extension designed to automate repetitive data entry, bulk form submissions, and web data extraction with spreadsheet integration.</p><p>Whether you need to fill hundreds of survey responses, populate CRM fields from an Excel sheet, or automate multi-step web workflows, Excellent Data Filler provides an intelligent, flexible, and robust automation engine directly within your browser.</p><hr><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to “Key Features”">​</a></h2><div class="key-features-grid"><div class="feature-card"><div class="feature-icon-wrapper"><img src="/svg/form.svg" width="22" height="22" alt="Form"></div><div class="feature-content"><div class="feature-title">Intelligent Form Auto-Fill</div><div class="feature-desc">Automatically detect and populate input fields with predefined values, dynamic variables, or spreadsheet rows.</div></div></div><div class="feature-card"><div class="feature-icon-wrapper"><img src="/svg/excel.svg" width="22" height="22" alt="Excel"></div><div class="feature-content"><div class="feature-title">Excel Integration</div><div class="feature-desc">Upload and import data directly from <code>.xlsx</code> files and automatically iterate through records row-by-row.</div></div></div><div class="feature-card"><div class="feature-icon-wrapper"><img src="/svg/click.svg" width="22" height="22" alt="Click"></div><div class="feature-content"><div class="feature-title">Smart Action Triggers</div><div class="feature-desc">Automate button clicks, modal interactions, tab navigation, and form submissions effortlessly.</div></div></div><div class="feature-card"><div class="feature-icon-wrapper"><img src="/svg/code.svg" width="22" height="22" alt="Code"></div><div class="feature-content"><div class="feature-title">Custom JavaScript Execution</div><div class="feature-desc">Execute custom JavaScript formulas and conditions to transform data and handle complex workflows dynamically.</div></div></div><div class="feature-card"><div class="feature-icon-wrapper"><img src="/svg/database.svg" width="22" height="22" alt="Database"></div><div class="feature-content"><div class="feature-title">Response Capture &amp; Logging</div><div class="feature-desc">Record submission results, track errors, and export detailed logs for auditing and reporting.</div></div></div><div class="feature-card"><div class="feature-icon-wrapper"><img src="/svg/globe.svg" width="22" height="22" alt="Globe"></div><div class="feature-content"><div class="feature-title">Universal Compatibility</div><div class="feature-desc">Works across Google Forms, Microsoft Forms, internal enterprise portals, and standard HTML web forms.</div></div></div><div class="feature-card"><div class="feature-icon-wrapper"><img src="/svg/template.svg" width="22" height="22" alt="Template"></div><div class="feature-content"><div class="feature-title">Reusable Site Configurations</div><div class="feature-desc">Save form field mappings into persistent templates to reuse across multiple sessions or team members.</div></div></div><div class="feature-card"><div class="feature-icon-wrapper"><img src="/svg/settings.svg" width="22" height="22" alt="Settings"></div><div class="feature-content"><div class="feature-title">Comprehensive Field Support</div><div class="feature-desc">Native support for text, email, numbers, dropdown selects, radio buttons, checkboxes, dates, and file uploads.</div></div></div></div><hr><h2 id="download-extension" tabindex="-1">Browser Availability &amp; Download <a class="header-anchor" href="#download-extension" aria-label="Permalink to “Browser Availability &amp; Download”">​</a></h2><p>Excellent Data Filler is built using Manifest V3 and is officially supported across all major Chromium and Gecko browsers:</p><table tabindex="0"><thead><tr><th style="text-align:center;"><img src="/logo/icons8-chrome-64.svg" alt="Chrome"></th><th style="text-align:center;"><img src="/logo/icons8-firefox-48.png" alt="Firefox"></th><th style="text-align:center;"><img src="/logo/icons8-edge-48.svg" alt="Edge"></th><th style="text-align:center;"><img src="/logo/icons8-opera-48.svg" alt="Opera"></th><th style="text-align:center;"><img src="/logo/icons8-safari-48.svg" alt="Safari"></th></tr></thead><tbody><tr><td style="text-align:center;"><strong>Google Chrome</strong></td><td style="text-align:center;"><strong>Mozilla Firefox</strong></td><td style="text-align:center;"><strong>Microsoft Edge</strong></td><td style="text-align:center;"><strong>Opera Browser</strong></td><td style="text-align:center;"><strong>Apple Safari</strong></td></tr><tr><td style="text-align:center;">Latest <img src="/svg/check.svg" class="doc-icon" width="14" height="14" alt="Supported"></td><td style="text-align:center;">Latest <img src="/svg/check.svg" class="doc-icon" width="14" height="14" alt="Supported"></td><td style="text-align:center;">Latest <img src="/svg/check.svg" class="doc-icon" width="14" height="14" alt="Supported"></td><td style="text-align:center;">Latest <img src="/svg/check.svg" class="doc-icon" width="14" height="14" alt="Supported"></td><td style="text-align:center;">Coming Soon</td></tr></tbody></table><h3 id="direct-store-links" tabindex="-1">Direct Store Links <a class="header-anchor" href="#direct-store-links" aria-label="Permalink to “Direct Store Links”">​</a></h3><ul><li><img src="/svg/globe.svg" class="doc-icon" width="16" height="16" alt="Chrome"> <a href="https://chrome.google.com/webstore/detail/excellent-data-filler-cth/abafaagbfhobgjkcepckbnadafflkdea" target="_blank" rel="noreferrer">Chrome Web Store (Official Release)</a></li><li><img src="/svg/code.svg" class="doc-icon" width="16" height="16" alt="Dev"> <a href="https://chromewebstore.google.com/detail/excellent-data-filler-dev/pkcdniljhopkooejgnidnfahljpnopgn" target="_blank" rel="noreferrer">Chrome Web Store (Developer / Beta Version)</a></li><li><img src="/svg/globe.svg" class="doc-icon" width="16" height="16" alt="Firefox"> <a href="https://addons.mozilla.org/en-US/firefox/addon/excellent-data-filler/" target="_blank" rel="noreferrer">Firefox Add-ons (Official Release)</a></li></ul><hr><h2 id="quick-start" tabindex="-1">Quick Start Guide <a class="header-anchor" href="#quick-start" aria-label="Permalink to “Quick Start Guide”">​</a></h2><p>Follow these 4 simple steps to automate your first web form in under 2 minutes:</p><h3 id="step-1-install-pin-the-extension" tabindex="-1">Step 1: Install &amp; Pin the Extension <a class="header-anchor" href="#step-1-install-pin-the-extension" aria-label="Permalink to “Step 1: Install &amp; Pin the Extension”">​</a></h3><ol><li>Install the extension from your browser&#39;s web store using the links above.</li><li>Pin the <strong>Excellent Data Filler</strong> icon to your browser toolbar for quick 1-click access.</li></ol><h3 id="step-2-register-a-new-site-configuration" tabindex="-1">Step 2: Register a New Site Configuration <a class="header-anchor" href="#step-2-register-a-new-site-configuration" aria-label="Permalink to “Step 2: Register a New Site Configuration”">​</a></h3><ol><li>Open the target web page containing the form you want to automate.</li><li>Click the extension toolbar icon or right-click anywhere on the form.</li><li>Select <strong>&quot;Insert Site&quot;</strong> from the context menu. The extension will automatically detect the page URL and prepare the field mapping schema.</li></ol><p><img src="/image/insert-site-01.png" alt="Insert Site"></p><h3 id="step-3-configure-form-fields-data-sources" tabindex="-1">Step 3: Configure Form Fields &amp; Data Sources <a class="header-anchor" href="#step-3-configure-form-fields-data-sources" aria-label="Permalink to “Step 3: Configure Form Fields &amp; Data Sources”">​</a></h3><ol><li>Open the <strong>Site Configuration</strong> dashboard from the extension popup.</li><li>Match each detected field to your desired data source: <ul><li><strong>Static Values</strong>: Fixed text, default choices, or boilerplate content.</li><li><strong>Excel Rows (.xlsx)</strong>: Map columns (e.g. <code>Column A</code>, <code>Column B</code>) from your uploaded <code>.xlsx</code> file directly to form inputs.</li><li><strong>Dynamic Variables</strong>: Timestamps, random numbers, UUIDs, or counter loops.</li><li><strong>Custom Scripting</strong>: Apply JavaScript conditions or calculations before insertion.</li></ul></li></ol><h3 id="step-4-run-automation-review-results" tabindex="-1">Step 4: Run Automation &amp; Review Results <a class="header-anchor" href="#step-4-run-automation-review-results" aria-label="Permalink to “Step 4: Run Automation &amp; Review Results”">​</a></h3><ol><li>Refresh or navigate to the form page — the extension will automatically detect the site configuration and fill the form fields.</li><li>You can quickly start or pause automation anytime using the keyboard shortcut <kbd>Alt</kbd> + <kbd>Q</kbd>, or by toggling the extension icon.</li><li>If any field or action needs troubleshooting, open the built-in <a href="/documentation/logs.html">Extension Logs</a> to review detailed execution steps and error diagnostics.</li></ol><blockquote><p><strong><img src="/svg/bulb.svg" class="doc-icon" width="18" height="18" alt="Tip"> Pro Tip:</strong> When working with large multi-page forms, configure small sections first to verify selector accuracy before running bulk batch imports.</p></blockquote><hr><h2 id="common-use-cases" tabindex="-1">Common Use Cases <a class="header-anchor" href="#common-use-cases" aria-label="Permalink to “Common Use Cases”">​</a></h2><h3 id="data-entry-automation" tabindex="-1"><img src="/svg/form.svg" class="doc-icon" width="20" height="20" alt="Data Entry"> Bulk Data Entry Automation <a class="header-anchor" href="#data-entry-automation" aria-label="Permalink to “Bulk Data Entry Automation”">​</a></h3><ul><li><strong>Customer Registration &amp; Onboarding</strong> — Rapidly fill out account creation forms and onboarding portals.</li><li><strong>Survey Submissions</strong> — Streamline responses across Google Forms, Microsoft Forms, and SurveyMonkey.</li><li><strong>Support Ticket Creation</strong> — Auto-populate repetitive fields in helpdesk systems like Zendesk or Jira.</li><li><strong>Job &amp; College Applications</strong> — Save hours by filling identical background questions automatically.</li></ul><h3 id="data-management" tabindex="-1"><img src="/svg/excel.svg" class="doc-icon" width="20" height="20" alt="Data Management"> Spreadsheet &amp; Database Workflows <a class="header-anchor" href="#data-management" aria-label="Permalink to “Spreadsheet &amp; Database Workflows”">​</a></h3><ul><li><strong>Row-by-Row Batch Processing</strong> — Automatically advance through spreadsheet rows after each successful form submission.</li><li><strong>Data Migration</strong> — Migrate legacy spreadsheet records into web-based ERP and CRM applications without manual copy-pasting.</li><li><strong>Automated Report Generation</strong> — Extract and assemble periodic form responses into structured Excel reports.</li></ul><h3 id="workflow-automation" tabindex="-1"><img src="/svg/browser.svg" class="doc-icon" width="20" height="20" alt="Workflow Automation"> Quality Assurance &amp; Testing <a class="header-anchor" href="#workflow-automation" aria-label="Permalink to “Quality Assurance &amp; Testing”">​</a></h3><ul><li><strong>Form Validation &amp; Stress Testing</strong> — Test edge-case inputs, special characters, and boundary conditions automatically.</li><li><strong>Regression Testing</strong> — Validate form submission flows during web application release cycles.</li><li><strong>Web Scraping &amp; Extraction</strong> — Extract structured tabular data from web pages into exportable formats.</li></ul><hr><h2 id="need-help" tabindex="-1">Need Help &amp; Support? <a class="header-anchor" href="#need-help" aria-label="Permalink to “Need Help &amp; Support?”">​</a></h2><h3 id="documentation" tabindex="-1"><img src="/svg/book.svg" class="doc-icon" width="20" height="20" alt="Documentation"> Documentation Guides <a class="header-anchor" href="#documentation" aria-label="Permalink to “Documentation Guides”">​</a></h3><ul><li>Explore the complete <a href="/documentation/">Documentation Overview</a> for in-depth setup instructions.</li><li>Learn about supported <a href="/documentation/form-fields/field-types.html">Field Types &amp; Selectors</a>.</li><li>Master dynamic automation with <a href="/documentation/functions.html">Functions and Variables</a>.</li></ul><h3 id="support-channels" tabindex="-1"><img src="/svg/support.svg" class="doc-icon" width="20" height="20" alt="Support"> Support Channels <a class="header-anchor" href="#support-channels" aria-label="Permalink to “Support Channels”">​</a></h3><ul><li><img src="/svg/youtube.svg" class="doc-icon" width="16" height="16" alt="YouTube"> <a href="https://www.youtube.com/@ctechhindi" target="_blank" rel="noreferrer">YouTube Channel</a> - Video tutorials and feature demos</li><li><img src="/svg/chat.svg" class="doc-icon" width="16" height="16" alt="Google Group"> <a href="https://groups.google.com/g/excellent-data-filler" target="_blank" rel="noreferrer">Google Group Forum</a> - Community discussions and tips</li><li><img src="/svg/whatsapp.svg" class="doc-icon" width="16" height="16" alt="WhatsApp"> <a href="https://chat.whatsapp.com/F2AdHoZRvr8HiAbvWqKlVS" target="_blank" rel="noreferrer">WhatsApp Group</a> - Real-time user support</li><li><img src="/svg/bug.svg" class="doc-icon" width="16" height="16" alt="Report Issues"> <a href="https://github.com/jeevan-lal/excellent-data-filler-docs/issues" target="_blank" rel="noreferrer">GitHub Issues</a> - Report bugs and request new features</li></ul><h3 id="testing-development" tabindex="-1"><img src="/svg/beaker.svg" class="doc-icon" width="20" height="20" alt="Testing"> Interactive Sandbox <a class="header-anchor" href="#testing-development" aria-label="Permalink to “Interactive Sandbox”">​</a></h3><ul><li><img src="/svg/code.svg" class="doc-icon" width="16" height="16" alt="Testing Site"> <a href="/documentation/testing-site.html">Interactive Testing Site</a> - Test your extension rules with live sample forms.</li><li><img src="/svg/settings.svg" class="doc-icon" width="16" height="16" alt="Development Version"> <a href="https://chromewebstore.google.com/detail/excellent-data-filler-dev/pkcdniljhopkooejgnidnfahljpnopgn" target="_blank" rel="noreferrer">Developer Build Channel</a> - Try the latest features and pre-release updates.</li></ul><h3 id="support-the-project" tabindex="-1"><img src="/svg/card.svg" class="doc-icon" width="20" height="20" alt="Support Project"> Support the Project <a class="header-anchor" href="#support-the-project" aria-label="Permalink to “Support the Project”">​</a></h3><ul><li><img src="/svg/card.svg" class="doc-icon" width="16" height="16" alt="PayPal"> <a href="https://www.paypal.com/paypalme/ctechhindi" target="_blank" rel="noreferrer">PayPal Donation</a> - Support ongoing development and maintenance.</li><li><img src="/svg/star.svg" class="doc-icon" width="16" height="16" alt="Star"> Star the <a href="https://github.com/jeevan-lal/excellent-data-filler-docs" target="_blank" rel="noreferrer">GitHub Repository</a> to show your support!</li></ul>`,43)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};